"use client"

import { useState, useEffect } from "react"
import { Navbar } from "@/components/navbar"
import { Footer } from "@/components/footer"
import dynamic from 'next/dynamic'
// Load Calendar only on the client to avoid SSR/client date formatting mismatches
const Calendar = dynamic(() => import('@/components/ui/calendar').then((m) => m.Calendar), { ssr: false })
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Card } from "@/components/ui/card"
import { Plus, Trash2 } from 'lucide-react'

const ANSWER_CATEGORIES = [
  "NBA Players",
  "NBA Teams",
  "NHL Players",
  "NHL Teams",
  "NFL Players",
  "NFL Teams",
]

  // Career path should only offer Player categories
  const CAREER_PLAYER_CATEGORIES = [
    "NFL Players",
    "NHL Players",
    "NBA Players",
  ]

export default function AddTriviaPage() {
  // Initialize `selectedDate` on the client to avoid server/client serialization
  // mismatches (hydration errors). Start undefined on the server and set a
  // concrete Date after mount.
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined)
  const [showForm, setShowForm] = useState(false)

  // Daily Quest state
  const [dailyQuestQuestions, setDailyQuestQuestions] = useState(
    Array(5).fill(null).map(() => ({ question: "", category: "" }))
  )
  const [dailyQuestAnswers, setDailyQuestAnswers] = useState(Array(5).fill(""))

  // Suggestions cache by db key
  const [suggestionsByDb, setSuggestionsByDb] = useState<Record<string, string[]>>({})

  // Fan Feud state
  const [fanFeudQuestion, setFanFeudQuestion] = useState("")
  const [fanFeudCategory, setFanFeudCategory] = useState("")
  const [fanFeudAnswers, setFanFeudAnswers] = useState(Array(8).fill(""))
  const [fanFeudSuggestions, setFanFeudSuggestions] = useState<string[]>([])

  // Career Path state
  const [careerPathCategory, setCareerPathCategory] = useState("")
  const [careerPathPlayer, setCareerPathPlayer] = useState("")
  const [careerPathTeams, setCareerPathTeams] = useState([""])
  const [careerPathPlayerSuggestions, setCareerPathPlayerSuggestions] = useState<string[]>([])
  const [careerPathTeamSuggestions, setCareerPathTeamSuggestions] = useState<string[]>([])
  const [dailyFocusedIndex, setDailyFocusedIndex] = useState<number | null>(null)
  const [fanFeudFocusedIndex, setFanFeudFocusedIndex] = useState<number | null>(null)
  const [careerPlayerFocused, setCareerPlayerFocused] = useState(false)
  const [careerTeamFocusedIndex, setCareerTeamFocusedIndex] = useState<number | null>(null)

  // map UI category -> server `db` query param
  const mapCategoryToDb = (category: string) => {
    switch (category) {
      case 'NBA Players': return 'nba_players'
      case 'NBA Teams': return 'nba_teams'
      case 'NHL Players': return 'nhl_players'
      case 'NHL Teams': return 'nhl_teams'
      case 'NFL Players': return 'nfl_players'
      case 'NFL Teams': return 'nfl_teams'
      default: return ''
    }
  }

  // normalize for matching: strip diacritics/punctuation, lowercase and trim
  const normalize = (text: string) =>
    text
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-zA-Z0-9 ]/g, "")
      .toLowerCase()
      .trim()

  const fetchAllNames = async (dbKey: string) => {
    if (!dbKey) return []
    try {
      // cache
      if (suggestionsByDb[dbKey]) return suggestionsByDb[dbKey]
      const res = await fetch(`/api/allnames?db=${encodeURIComponent(dbKey)}`)
      if (!res.ok) return []
      const data = await res.json()
      setSuggestionsByDb((prev) => ({ ...prev, [dbKey]: data }))
      return data
    } catch (e) {
      return []
    }
  }

  const handleDateSelect = (date: Date | undefined) => {
    setSelectedDate(date)
    if (date) {
      setShowForm(true)
    }
  }

  // On client mount, set the default date to today. This avoids the server
  // rendering a Date-derived attribute that may format differently than the
  // client (causing hydration mismatch errors).
  useEffect(() => {
    if (selectedDate === undefined) setSelectedDate(new Date())
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const handleAddTeam = () => {
    setCareerPathTeams([...careerPathTeams, ""])
  }

  const handleRemoveTeam = (index: number) => {
    if (careerPathTeams.length > 1) {
      setCareerPathTeams(careerPathTeams.filter((_, i) => i !== index))
    }
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()

    // Validation: ensure every answer input is filled and matches a suggestion exactly
    // Daily Quest answers
    for (let i = 0; i < dailyQuestQuestions.length; i++) {
      const q = dailyQuestQuestions[i]
      const ans = (dailyQuestAnswers[i] || '').trim()
      if (!q.question || !q.category) {
        alert(`Daily Quest question ${i+1} is missing question or category`)
        return
      }
      const db = mapCategoryToDb(q.category)
      const opts = suggestionsByDb[db] || []
      if (!opts.length) {
        alert(`No suggestions loaded for category ${q.category}. Please select the category to load suggestions.`)
        return
      }
      const match = opts.find((o) => o === ans)
      if (!match) {
        alert(`Daily Quest answer ${i+1} must exactly match a suggestion from the ${q.category} list.`)
        return
      }
    }

    // Fan Feud answers
    if (!fanFeudQuestion || !fanFeudCategory) {
      alert('Fan Feud question and category are required')
      return
    }
    const ffDb = mapCategoryToDb(fanFeudCategory)
    const ffOpts = suggestionsByDb[ffDb] || []
    if (!ffOpts.length) {
      alert(`No suggestions loaded for Fan Feud category ${fanFeudCategory}`)
      return
    }
    for (let i = 0; i < fanFeudAnswers.length; i++) {
      const a = (fanFeudAnswers[i] || '').trim()
      if (!a) {
        alert(`Fan Feud answer ${i+1} is required and must match a suggestion`)
        return
      }
      if (!ffOpts.includes(a)) {
        alert(`Fan Feud answer ${i+1} must exactly match a suggestion from ${fanFeudCategory}`)
        return
      }
    }

    // Career Path answers
    if (!careerPathCategory) {
      alert('Career Path category is required')
      return
    }
    const playerOpts = careerPathPlayerSuggestions || []
    const teamOpts = careerPathTeamSuggestions || []
    if (!playerOpts.length) {
      alert(`No player suggestions loaded for Career Path category ${careerPathCategory}`)
      return
    }
    if (!teamOpts.length) {
      alert(`No team suggestions loaded for Career Path category ${careerPathCategory}`)
      return
    }
    // player must match
    if (!careerPathPlayer.trim() || !playerOpts.includes(careerPathPlayer.trim())) {
      alert('Career Path player must exactly match a suggestion for the selected category')
      return
    }
    // teams must match (use teams list)
    for (let i = 0; i < careerPathTeams.length; i++) {
      const t = (careerPathTeams[i] || '').trim()
      if (!t || !teamOpts.includes(t)) {
        alert(`Career Path team ${i+1} must exactly match a team suggestion from ${careerPathCategory}`)
        return
      }
    }

    // Build payload for server
    const dateKey = selectedDate ? selectedDate.toISOString().split('T')[0] : new Date().toISOString().split('T')[0]

    const dailyQuestionsPayload = dailyQuestQuestions.map((q, idx) => ({
      text: q.question,
      answer: (dailyQuestAnswers[idx] || '').trim(),
      answersDb: mapCategoryToDb(q.category),
    }))

    const fanFeudPayload = {
      question: fanFeudQuestion,
      answersDb: mapCategoryToDb(fanFeudCategory),
      answers: fanFeudAnswers.map((a) => (a || '').trim()),
    }

    const careerPathPayload = {
      playerName: careerPathPlayer.trim(),
      answersTable: mapCategoryToDb(careerPathCategory),
      teams: careerPathTeams.map((t) => (t || '').trim()),
    }

    const payload = {
      date: dateKey,
      dailyQuestions: dailyQuestionsPayload,
      fanFeud: fanFeudPayload,
      careerPath: careerPathPayload,
    }

    // Send to backend admin route
    ;(async () => {
      try {
        const token = typeof window !== 'undefined' ? localStorage.getItem('accessToken') : null
        const headers: Record<string,string> = { 'Content-Type': 'application/json' }
        if (token) headers['Authorization'] = `Bearer ${token}`

        const res = await fetch('/api/admin/add-questions', {
          method: 'POST',
          headers,
          body: JSON.stringify(payload),
        })

        if (!res.ok) {
          const err = await res.json().catch(() => ({ error: 'Unknown error' }))
          console.error('Failed to submit trivia:', err)
          alert('Failed to submit trivia: ' + (err.error || res.statusText))
          return
        }

        const data = await res.json()
        console.log('Add questions response:', data)
        alert('Trivia submitted successfully!')
        // Optionally reset form or navigate away
        setShowForm(false)
      } catch (error) {
        console.error('Submit error:', error)
        alert('Failed to submit trivia: ' + (error && error.message ? error.message : String(error)))
      }
    })()
  }

  return (
    <>
      <Navbar />
      <div className="min-h-screen w-full bg-[#2eaafd] pt-24 pb-16 px-4">
        <div className="container mx-auto max-w-6xl">
          <h1 className="text-4xl font-bold text-white text-center mb-8">Add Trivia Questions</h1>

          {!showForm ? (
            <Card className="bg-white/95 backdrop-blur-sm p-8 max-w-md mx-auto">
              <h2 className="text-2xl font-bold text-[#152a4d] mb-4 text-center">Select a Date</h2>
              <Calendar
                mode="single"
                selected={selectedDate}
                onSelect={handleDateSelect}
                className="rounded-md border"
              />
            </Card>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-8">
              <Card className="bg-white/95 backdrop-blur-sm p-6">
                <div className="flex justify-between items-center mb-6">
                  <h2 className="text-2xl font-bold text-[#152a4d]">
                    Trivia for {selectedDate?.toLocaleDateString()}
                  </h2>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => setShowForm(false)}
                  >
                    Change Date
                  </Button>
                </div>

                {/* Daily Quest Questions */}
                <div className="mb-8">
                  <h3 className="text-xl font-bold text-[#152a4d] mb-4">Daily Quest Questions</h3>
                  <div className="space-y-4">
                    {dailyQuestQuestions.map((q, i) => (
                      <div key={i} className="border border-gray-200 rounded-lg p-4 bg-gray-50">
                        <Label className="text-base font-semibold mb-2 block">Question {i + 1}</Label>
                        <Input
                          placeholder="Enter trivia question"
                          value={q.question}
                          onChange={(e) => {
                            const updated = [...dailyQuestQuestions]
                            updated[i].question = e.target.value
                            setDailyQuestQuestions(updated)
                          }}
                          className="mb-2"
                          required
                        />

                        <div>
                          <Label className="text-sm font-medium mb-1">Answer</Label>
                          <div className="relative">
                            <Input
                              placeholder="Type or select an answer"
                              value={dailyQuestAnswers[i]}
                              onChange={(e) => {
                                const val = e.target.value
                                const updated = [...dailyQuestAnswers]
                                updated[i] = val
                                setDailyQuestAnswers(updated)
                              }}
                              onFocus={() => { setDailyFocusedIndex(i); setFanFeudFocusedIndex(null); setCareerPlayerFocused(false); setCareerTeamFocusedIndex(null) }}
                              onBlur={() => { setTimeout(() => setDailyFocusedIndex((idx) => (idx === i ? null : idx)), 150) }}
                              className="mb-2"
                              required
                            />
                            {/* Custom suggestion dropdown (styled), filtered by current input */}
                            {dailyFocusedIndex === i && (() => {
                              const db = mapCategoryToDb(q.category)
                              const opts = suggestionsByDb[db] || []
                              if (!opts.length) return null
                              const normalizedInput = normalize((dailyQuestAnswers[i] || ""))
                              const filtered = normalizedInput
                                ? opts.filter((n) => normalize(n).includes(normalizedInput)).slice(0, 50)
                                : opts.slice(0, 50)
                              return (
                                <div className="absolute left-0 right-0 mt-1 bg-white/95 border border-white/10 rounded-md shadow-lg max-h-56 overflow-auto z-50">
                                  {filtered.map((s) => (
                                    <div
                                      key={s}
                                      onMouseDown={() => {
                                        const updated = [...dailyQuestAnswers]
                                        updated[i] = s
                                        setDailyQuestAnswers(updated)
                                        setDailyFocusedIndex(null)
                                      }}
                                      className="px-3 py-2 hover:bg-blue-50 cursor-pointer text-sm text-slate-800"
                                    >
                                      {s}
                                    </div>
                                  ))}
                                </div>
                              )
                            })()}
                          </div>
                        </div>

                        <Select
                          value={q.category}
                          onValueChange={(value) => {
                            const updated = [...dailyQuestQuestions]
                            updated[i].category = value
                            setDailyQuestQuestions(updated)
                            // preload suggestions for this category into cache
                            const db = mapCategoryToDb(value)
                            if (db) fetchAllNames(db)
                          }}
                          required
                        >
                          <SelectTrigger>
                            <SelectValue placeholder="Select answer category" />
                          </SelectTrigger>
                          <SelectContent>
                            {ANSWER_CATEGORIES.map((cat) => (
                              <SelectItem key={cat} value={cat}>
                                {cat}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Fan Feud */}
                <div className="mb-8">
                  <h3 className="text-xl font-bold text-[#152a4d] mb-4">Fan Feud Question</h3>
                  <div className="space-y-4">
                    <div>
                      <Label>Trivia Question</Label>
                      <Input
                        placeholder="Enter Fan Feud question"
                        value={fanFeudQuestion}
                        onChange={(e) => setFanFeudQuestion(e.target.value)}
                        required
                      />
                    </div>
                    <div>
                      <Label>Answer Category</Label>
                      <Select
                        value={fanFeudCategory}
                        onValueChange={(val) => {
                          setFanFeudCategory(val)
                          const db = mapCategoryToDb(val)
                          if (db) fetchAllNames(db).then((names) => setFanFeudSuggestions(names || []))
                        }}
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="Select answer category" />
                        </SelectTrigger>
                        <SelectContent>
                          {ANSWER_CATEGORIES.map((cat) => (
                            <SelectItem key={cat} value={cat}>
                              {cat}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      {fanFeudAnswers.map((answer, i) => (
                        <div key={i}>
                          <Label>Answer {i + 1}</Label>
                          <>
                            <div className="relative">
                              <Input
                                placeholder={`Answer ${i + 1}`}
                                value={answer}
                                onChange={(e) => {
                                  const updated = [...fanFeudAnswers]
                                  updated[i] = e.target.value
                                  setFanFeudAnswers(updated)
                                }}
                                onFocus={() => { setFanFeudFocusedIndex(i); setDailyFocusedIndex(null); setCareerPlayerFocused(false); setCareerTeamFocusedIndex(null) }}
                                onBlur={() => { setTimeout(() => setFanFeudFocusedIndex((idx) => (idx === i ? null : idx)), 150) }}
                                required={i === 0}
                              />
                              {fanFeudFocusedIndex === i && (() => {
                                const opts = fanFeudSuggestions || []
                                if (!opts.length) return null
                                const normalizedInput = normalize((fanFeudAnswers[i] || ""))
                                const filtered = normalizedInput
                                  ? opts.filter((n) => normalize(n).includes(normalizedInput)).slice(0, 50)
                                  : opts.slice(0, 50)
                                return (
                                  <div className="absolute left-0 right-0 mt-1 bg-white/95 border border-white/10 rounded-md shadow-lg max-h-56 overflow-auto z-50">
                                    {filtered.map((s) => (
                                      <div
                                        key={s}
                                        onMouseDown={() => {
                                          const updated = [...fanFeudAnswers]
                                          updated[i] = s
                                          setFanFeudAnswers(updated)
                                          setFanFeudFocusedIndex(null)
                                        }}
                                        className="px-3 py-2 hover:bg-blue-50 cursor-pointer text-sm text-slate-800"
                                      >
                                        {s}
                                      </div>
                                    ))}
                                  </div>
                                )
                              })()}
                            </div>
                          </>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                {/* Career Path */}
                <div className="mb-8">
                  <h3 className="text-xl font-bold text-[#152a4d] mb-4">Career Path</h3>
                  <div className="space-y-4">
                    <div>
                      <Label>Answer Category</Label>
                      <Select
                        value={careerPathCategory}
                        onValueChange={(val) => {
                          setCareerPathCategory(val)
                          // players db (e.g. nfl_players)
                          const playersDb = mapCategoryToDb(val)
                          // derive teams db from player category (e.g. nfl_teams)
                          const teamsDb = (() => {
                            switch (val) {
                              case 'NFL Players': return 'nfl_teams'
                              case 'NHL Players': return 'nhl_teams'
                              case 'NBA Players': return 'nba_teams'
                              default: return ''
                            }
                          })()

                          if (playersDb) fetchAllNames(playersDb).then((names) => setCareerPathPlayerSuggestions(names || []))
                          if (teamsDb) fetchAllNames(teamsDb).then((names) => setCareerPathTeamSuggestions(names || []))
                        }}
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="Select answer category" />
                        </SelectTrigger>
                        <SelectContent>
                          {CAREER_PLAYER_CATEGORIES.map((cat) => (
                            <SelectItem key={cat} value={cat}>
                              {cat}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div>
                      <Label>Player Answer</Label>
                      <div className="relative">
                        <Input
                          placeholder="Enter player name"
                          value={careerPathPlayer}
                          onChange={(e) => setCareerPathPlayer(e.target.value)}
                          onFocus={() => { setCareerPlayerFocused(true); setDailyFocusedIndex(null); setFanFeudFocusedIndex(null); setCareerTeamFocusedIndex(null) }}
                          onBlur={() => { setTimeout(() => setCareerPlayerFocused(false), 150) }}
                          required
                        />
                        {careerPlayerFocused && (() => {
                          const opts = careerPathPlayerSuggestions || []
                          if (!opts.length) return null
                          const normalizedInput = normalize(careerPathPlayer || "")
                          const filtered = normalizedInput
                            ? opts.filter((n) => normalize(n).includes(normalizedInput)).slice(0, 50)
                            : opts.slice(0, 50)
                          return (
                            <div className="absolute left-0 right-0 mt-1 bg-white/95 border border-white/10 rounded-md shadow-lg max-h-56 overflow-auto z-50">
                              {filtered.map((s) => (
                                <div
                                  key={s}
                                  onMouseDown={() => {
                                    setCareerPathPlayer(s)
                                    setCareerPlayerFocused(false)
                                  }}
                                  className="px-3 py-2 hover:bg-blue-50 cursor-pointer text-sm text-slate-800"
                                >
                                  {s}
                                </div>
                              ))}
                            </div>
                          )
                        })()}
                      </div>
                    </div>
                    <div>
                      <div className="flex justify-between items-center mb-2">
                        <Label>Teams (in chronological order)</Label>
                        <Button
                          type="button"
                          size="sm"
                          onClick={handleAddTeam}
                          className="bg-[#2a569c] hover:bg-[#1e4070]"
                        >
                          <Plus className="w-4 h-4 mr-1" />
                          Add Team
                        </Button>
                      </div>
                      <div className="space-y-2">
                        {careerPathTeams.map((team, i) => (
                          <div key={i} className="flex gap-2">
                            <div className="relative flex-1">
                              <Input
                                placeholder={`Team ${i + 1}`}
                                value={team}
                                onChange={(e) => {
                                  const updated = [...careerPathTeams]
                                  updated[i] = e.target.value
                                  setCareerPathTeams(updated)
                                }}
                                onFocus={() => { setCareerTeamFocusedIndex(i); setDailyFocusedIndex(null); setFanFeudFocusedIndex(null); setCareerPlayerFocused(false) }}
                                onBlur={() => { setTimeout(() => setCareerTeamFocusedIndex((idx) => (idx === i ? null : idx)), 150) }}
                                required={i === 0}
                              />
                              {careerTeamFocusedIndex === i && (() => {
                                const opts = careerPathTeamSuggestions || []
                                if (!opts.length) return null
                                const normalizedInput = normalize((careerPathTeams[i] || ""))
                                const filtered = normalizedInput
                                  ? opts.filter((n) => normalize(n).includes(normalizedInput)).slice(0, 50)
                                  : opts.slice(0, 50)
                                return (
                                  <div className="absolute left-0 right-0 mt-1 bg-white/95 border border-white/10 rounded-md shadow-lg max-h-56 overflow-auto z-50">
                                    {filtered.map((s) => (
                                      <div
                                        key={s}
                                        onMouseDown={() => {
                                          const updated = [...careerPathTeams]
                                          updated[i] = s
                                          setCareerPathTeams(updated)
                                          setCareerTeamFocusedIndex(null)
                                        }}
                                        className="px-3 py-2 hover:bg-blue-50 cursor-pointer text-sm text-slate-800"
                                      >
                                        {s}
                                      </div>
                                    ))}
                                  </div>
                                )
                              })()}
                            </div>
                            {careerPathTeams.length > 1 && (
                              <Button
                                type="button"
                                size="icon"
                                variant="destructive"
                                onClick={() => handleRemoveTeam(i)}
                              >
                                <Trash2 className="w-4 h-4" />
                              </Button>
                            )}
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>

                <Button
                  type="submit"
                  size="lg"
                  className="w-full bg-[#2a569c] hover:bg-[#1e4070] text-white font-bold text-lg"
                >
                  Submit Trivia
                </Button>
              </Card>
            </form>
          )}
        </div>
      </div>
      <Footer />
    </>
  )
}
